import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits (0 <= k <= 7).

    Bits shifted out of the high end wrap around to the low end.
    The result is always within 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    assert rotl8(0b10110010, 0) == 0b10110010
    assert rotl8(0, 0) == 0
    assert rotl8(255, 0) == 255


def test_rotl8_wraps_high_bit() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0x80, 1) == 0x01


def test_rotl8_single_bit_positions() -> None:
    assert rotl8(1, 1) == 2
    assert rotl8(1, 7) == 128
    assert rotl8(0x80, 7) == 0x40


def test_rotl8_all_ones_is_fixed() -> None:
    for k in range(8):
        assert rotl8(255, k) == 255


def test_rotl8_known_values() -> None:
    assert rotl8(0xAB, 4) == 0xBA
    assert rotl8(0b00001111, 2) == 0b00111100


def test_rotl8_result_in_byte_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_composition_adds_shifts() -> None:
    for x in (0, 1, 0x5A, 0xF0, 255):
        for a in range(8):
            for b in range(8 - a):
                assert rotl8(rotl8(x, a), b) == rotl8(x, a + b)
